mapper.select:
select id, qualification_no, member_id, player_id, qualification_status, is_current, payment_confirmed, payment_reference, grant_reason, granted_by, granted_time, valid_from, valid_to, revoked_by, revoked_time, revoke_reason, create_time, update_time, is_delete from basket_captain_qualification
where is_delete = 0
and qualification_no like concat('%', #{qualificationNo}, '%')
and member_id = #{memberId}
and player_id = #{playerId}
and qualification_status = #{qualificationStatus}
order by granted_time desc
